"use client"

// Dependencies: npm i gsap @gsap/react

// Circle Reveal Loader — Goodmotion
// Website: https://goodmotion.vercel.app/

import React, { useRef, useState, useEffect } from "react"
import { createPortal } from "react-dom"
import gsap from "gsap"
import { useGSAP } from "@gsap/react"

export interface RippleRevealWaveProps {
    color1?: string
    color2?: string
    color3?: string
    duration?: number
    staggerOverlap?: number
    ease?: string
    onComplete?: () => void
    style?: React.CSSProperties
    className?: string
    children?: React.ReactNode
}

export function RippleRevealWave({
    color1 = "#F5C225",
    color2 = "#F05C15",
    color3 = "#CE2518",
    duration = 0.85,
    staggerOverlap = 0.58,
    ease = "power3.inOut",
    onComplete,
    style,
    className,
    children,
}: RippleRevealWaveProps) {
    const [isComplete, setIsComplete] = useState(false)
    const [mounted, setMounted] = useState(false)

    const containerRef = useRef<HTMLDivElement>(null)
    const panelRef = useRef<HTMLDivElement>(null)
    const layer1Ref = useRef<HTMLDivElement>(null)
    const layer2Ref = useRef<HTMLDivElement>(null)
    const layer3Ref = useRef<HTMLDivElement>(null)

    useEffect(() => {
        setMounted(true)
    }, [])

    useGSAP(
        () => {
            if (!mounted) return

            const panel = panelRef.current
            const l1 = layer1Ref.current
            const l2 = layer2Ref.current
            const l3 = layer3Ref.current

            if (!panel || !l1 || !l2 || !l3) return

            const w = window.innerWidth
            const h = window.innerHeight
            const maxRadius = Math.ceil(Math.hypot(w, h)) * 1.2

            gsap.set(l1, {
                clipPath: `circle(${maxRadius}px at 50% 0px)`,
                WebkitClipPath: `circle(${maxRadius}px at 50% 0px)`,
            })

            gsap.set([l2, l3], {
                clipPath: "circle(0px at 50% 0px)",
                WebkitClipPath: "circle(0px at 50% 0px)",
            })

            const initialMask =
                "radial-gradient(circle at 50% 0px, transparent 0px, #000 1px)"
            panel.style.maskImage = initialMask
            panel.style.webkitMaskImage = initialMask

            const tl = gsap.timeline({
                onComplete: () => {
                    setIsComplete(true)
                    if (onComplete) onComplete()
                },
            })

            tl.to(
                l2,
                {
                    clipPath: `circle(${maxRadius}px at 50% 0px)`,
                    WebkitClipPath: `circle(${maxRadius}px at 50% 0px)`,
                    duration,
                    ease,
                },
                0.05
            )

            tl.to(
                l3,
                {
                    clipPath: `circle(${maxRadius}px at 50% 0px)`,
                    WebkitClipPath: `circle(${maxRadius}px at 50% 0px)`,
                    duration,
                    ease,
                },
                `-=${staggerOverlap}`
            )

            const holeObj = { value: 0 }
            tl.to(
                holeObj,
                {
                    value: maxRadius,
                    duration,
                    ease,
                    onUpdate: () => {
                        const maskStr = `radial-gradient(circle at 50% 0px, transparent ${holeObj.value}px, #000 ${holeObj.value + 1}px)`
                        panel.style.maskImage = maskStr
                        panel.style.webkitMaskImage = maskStr
                    },
                },
                `-=${staggerOverlap}`
            )
        },
        {
            scope: containerRef,
            dependencies: [
                mounted,
                color1,
                color2,
                color3,
                duration,
                staggerOverlap,
                ease,
                onComplete,
            ],
        }
    )

    if (isComplete || !mounted || typeof document === "undefined") {
        return null
    }

    const overlayContent = (
        <div
            ref={containerRef}
            className={className}
            style={{
                position: "fixed",
                top: 0,
                left: 0,
                width: "100vw",
                height: "100vh",
                zIndex: 999999,
                pointerEvents: "none",
                backgroundColor: "transparent",
                overflow: "hidden",
                ...style,
            }}
        >
            <div
                ref={panelRef}
                style={{
                    position: "absolute",
                    inset: 0,
                    width: "100%",
                    height: "100%",
                    pointerEvents: "none",
                    willChange: "mask-image, -webkit-mask-image",
                }}
            >
                <div
                    ref={layer1Ref}
                    style={{
                        position: "absolute",
                        inset: 0,
                        backgroundColor: color1,
                        willChange: "clip-path, -webkit-clip-path",
                    }}
                />
                <div
                    ref={layer2Ref}
                    style={{
                        position: "absolute",
                        inset: 0,
                        backgroundColor: color2,
                        clipPath: "circle(0px at 50% 0px)",
                        WebkitClipPath: "circle(0px at 50% 0px)",
                        willChange: "clip-path, -webkit-clip-path",
                    }}
                />
                <div
                    ref={layer3Ref}
                    style={{
                        position: "absolute",
                        inset: 0,
                        backgroundColor: color3,
                        clipPath: "circle(0px at 50% 0px)",
                        WebkitClipPath: "circle(0px at 50% 0px)",
                        willChange: "clip-path, -webkit-clip-path",
                    }}
                />
            </div>
            {children}
        </div>
    )

    return createPortal(overlayContent, document.body)
}

export { RippleRevealWave as CircleRevealLoader }
export const Component = RippleRevealWave;
export default RippleRevealWave;

